// "Why these clues worked" at 320 px, 390 px and desktop, with four long x04
// explanations. The board is generated by the app's own generateBoard from four
// chosen library pairs, saved as the in-progress game, solved, and the reveal
// opened. At 320 the board is solved at 390 first (the tray sits below the fold
// for the drag helper) and the open sheet is then resized. Checks: each reveal
// item shows the explanation sentence and both per-word lines, nothing overflows
// sideways. Screenshots carry the test banner (test-only DOM) when a dir is given.
//   FRIENDS_E2E_URL=http://127.0.0.1:5192 node tests/unlimited/reveal-widths.mjs [screenshot-dir]
import fs from "node:fs";
import path from "node:path";
import assert from "node:assert/strict";
import puppeteer from "puppeteer-core";
import { CHROME } from "../friends/browser.mjs";
import { solve } from "../friends/board.mjs";
import { generateBoard } from "../../src/unlimited/generate.js";
import { startBoard, emptyStore } from "../../src/unlimited/history.js";

const URL = process.env.FRIENDS_E2E_URL || "http://127.0.0.1:5192";
const OUT = process.argv[2] ? path.resolve(process.argv[2]) : null;
if (OUT) fs.mkdirSync(OUT, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const lib = JSON.parse(fs.readFileSync("src/unlimited/random-library.json", "utf8"));
const WANT = ["p_crown__iron", "p_axe__king", "p_bath__sport", "p_crow__movie"];
const chosen = WANT.map((id) => lib.pairs.find((p) => p.id === id));
assert.ok(chosen.every(Boolean), "the four sample pairs are served by the client library");
const board = generateBoard({ ...lib, pairs: chosen }, { seed: 4242, createdAt: "2026-10-19T12:00:00.000Z", idSuffix: "revealwidth" });
assert.ok(board, "board generated");

const browser = await puppeteer.launch({ executablePath: CHROME, headless: true });
const errors = [];
const results = [];
const banner = (page, text) => page.evaluate((t) => { const d = document.createElement("div"); d.textContent = t; d.style.cssText = "position:fixed;top:0;left:0;right:0;z-index:99999;background:#b00;color:#fff;font:600 12px sans-serif;padding:4px;text-align:center"; document.body.appendChild(d); }, text);
const check = (page) => page.evaluate(() => ({
  sideways: document.documentElement.scrollWidth - window.innerWidth,
  items: [...document.querySelectorAll("[data-testid=ul-why-item]")].map((li) => {
    const ex = li.querySelector("[data-testid=ul-why-explain]");
    return { text: li.innerText, explain: ex?.textContent || "", overflow: [...li.querySelectorAll("*")].some((e) => e.scrollWidth - e.clientWidth > 1 && getComputedStyle(e).overflowX !== "visible") };
  }),
}));
try {
  for (const vp of [{ name: "phone-390", width: 390, height: 844, deviceScaleFactor: 2, isMobile: true, hasTouch: true, alsoAt: { name: "phone-320", width: 320, height: 568, deviceScaleFactor: 2, isMobile: true, hasTouch: true } }, { name: "desktop", width: 1280, height: 860, deviceScaleFactor: 1 }]) {
    const ctx = await browser.createBrowserContext();
    const page = await ctx.newPage();
    page.on("pageerror", (e) => errors.push(`${vp.name}: ${e.message}`));
    await page.setViewport(vp);
    await page.goto(URL, { waitUntil: "networkidle0" });
    await page.evaluate((s) => { localStorage.setItem("clover_tutorial_seen", "true"); localStorage.setItem("cv_unlimited_v1", JSON.stringify(s)); }, startBoard(emptyStore(), board, "standard"));
    await page.goto(`${URL}/unlimited`, { waitUntil: "networkidle0" });
    await page.waitForSelector(".game .csurface .ctile"); await sleep(1000);
    await solve(page, { cards: board.cards, solution: board.solution });
    await page.locator("button.sbtn").click();
    await page.waitForSelector("[data-testid=ul-end]", { timeout: 25000 }); await sleep(700);
    await page.locator("[data-testid=ul-why]").click();
    await page.waitForSelector("[data-testid=ul-why-item]"); await sleep(500);
    for (const size of [vp, vp.alsoAt].filter(Boolean)) {
      if (size !== vp) { await page.setViewport(size); await sleep(600); }
      const r = await check(page);
      board.reveal.forEach((rv) => assert.ok(r.items.some((it) => it.explain === rv.revealExplanation && it.text.includes(rv.wordAConnection) && it.text.includes(rv.wordBConnection)), `${size.name}: ${rv.clue} explanation and both lines shown`));
      results.push({ viewport: size.name, sideways: r.sideways, overflowingItems: r.items.filter((i) => i.overflow).length });
      if (OUT) { await banner(page, `TEST DATA / LOCAL x04 BUILD · ${size.name} · reveal`); await page.screenshot({ path: path.join(OUT, `reveal-${size.name}.png`) }); }
    }
    await ctx.close();
  }
  console.log(JSON.stringify(results, null, 1));
  assert.deepEqual(errors, [], "no page errors");
  for (const r of results) { assert.ok(r.sideways <= 0, `${r.viewport}: no sideways scroll`); assert.equal(r.overflowingItems, 0, `${r.viewport}: nothing clipped`); }
  console.log("\nPASS — reveal shows each explanation sentence and both per-word lines at 320, 390 and 1280 with no sideways scroll");
} finally { await browser.close(); }
